// Exact arithmetic variants build fluency without pretending to be true papers.
for(const [base,rate] of [[80,25],[120,20],[200,15],[240,25],[320,12.5],[400,20],[600,10],[800,12.5]]){const current=base*(1+rate/100),delta=current-base;civilQ('资料分析','基期还原',`某产品本期销量为${current}件，同比增长${rate}%，上期销量是多少件？`,base,[base+delta,base-delta,base+10],`本期=上期×(1+r)，所以上期=${current}÷${1+rate/100}=${base}件。增长率的分母是上期。`,'base');civilQ('资料分析','增长量',`本期销量${current}件，同比增长${rate}%，同比增加多少件？`,delta,[current*rate/100,base,current],`增长量=C×r/(1+r)=${current}×${rate/100}÷${1+rate/100}=${delta}。不能用本期直接乘增速。`,'fraction-growth');}
for(const [a,b] of [[20,25],[40,50],[60,66],[80,84]]){civilQ('资料分析','百分点',`某比例从${a}%提升到${b}%，提高多少个百分点？`,b-a,[Math.round((b-a)/a*100),b,a],`百分点直接相减：${b}−${a}=${b-a}个百分点。相对增长率是另一种问题。`,'percent');}
for(const [n,d] of [[480,8],[640,8],[900,4],[750,5],[1200,8],[360,4]])civilQ('资料分析','百化分',`${n}的${100/d}%等于多少？`,n/d,[n/d+10,n/d-10,n/(d+1)],`${100/d}%=${1}/${d}，所以${n}÷${d}=${n/d}。精确常用分数可直接化乘为除。`,'ratio');
civilQ('资料分析','截位直除','1980÷4010最接近下列哪个百分比？','50%',['30%','40%','60%'],'1980接近2000，4010接近4000，商约0.5。选项间隔10个百分点，这一精度足够；精确约49.38%。','truncate');
civilQ('资料分析','分数比较','下列哪一个分数最大？','7/15',['9/20','4/9','11/25'],'7/15≈0.4667。与9/20交叉比140与135；另两项约0.4444、0.44。','cross');
civilQ('资料分析','混合增长','甲地基期量300、增长10%，乙地基期量100、增长30%。两地合计增长率是多少？','15%',['20%','10%','30%'],'总增量=30+30=60，基期总量400；60÷400=15%。不能简单平均两个增速。','weighted');
civilQ('资料分析','两期比重','本期某部分占整体30%，部分同比增长20%，整体同比增长10%。比重比上期提高多少个百分点？','2.5',['10','5','3'],'基期比重=30%×1.1÷1.2=27.5%，提高30%−27.5%=2.5个百分点。先用20%>10%判断上升。','share');
civilQ('资料分析','增长量比较','甲本期120、增速20%；乙本期220、增速10%。两者增长量关系是什么？','相等',['甲大','乙大','无法比较'],'甲120×20%÷1.2=20；乙220×10%÷1.1=20。增速更高不等于增量更大。','compare-growth');
for(let i=0;i<4;i++){const x=100+i*20,material=`教学企业销售数据（单位：万元）：甲期${x}，乙期${x*1.2}，丙期${x*1.5}。各期口径一致。`,extra={material,materialId:'zx-material-'+i,paper:'知行原创 · 材料组 '+(i+1)};civilQ('资料分析','材料组题','乙期比甲期增长多少？','20%',['15%','25%','30%'],`增长率=(${x*1.2}−${x})÷${x}=20%。`,'base',extra);civilQ('资料分析','材料组题','丙期比甲期增加多少万元？',x*.5,[x*.2,x*.3,x],`增长量=${x*1.5}−${x}=${x*.5}。先确定问的是量而非率。`,'read',extra);civilQ('资料分析','材料组题','三期销售总量是多少万元？',x*3.7,[x*3.5,x*3.2,x*4],`${x}+${x*1.2}+${x*1.5}=${x*3.7}万元。注意各期可以相加的口径条件。`,'read',extra);}
for(const [a,b] of [[6,3],[12,6],[10,15],[8,24],[20,30],[9,18]]){const t=a*b/(a+b);civilQ('数量关系','工程问题',`甲单独${a}天、乙单独${b}天完成一项工程，两人效率恒定，合做需要多少天？`,t,[a+b,Math.min(a,b),t+1],`总量设为${a*b}份，甲效率${b}，乙效率${a}，合做${a*b}÷(${a}+${b})=${t}天。`,'special');}
for(const [p,d] of [[50,20],[80,25],[100,10],[200,20]])civilQ('数量关系','折扣方程',`某商品原价未知，降价${d}%后售价${p*(1-d/100)}元。原价是多少元？`,p,[p+d,p-d,p*(1-d/100)],`设原价x，x×${1-d/100}=${p*(1-d/100)}，解得x=${p}元。`,'equation');
for(const exp of [2025,2026,2027,2028]){const ans=[1,7,9,3][exp%4];civilQ('数量关系','尾数周期',`7的${exp}次方的个位数是多少？`,ans,[1,3,7,9].filter(x=>x!==ans),`7的幂个位周期为7、9、3、1。${exp}÷4余${exp%4}，余0看第4位，所以个位为${ans}。`,'tail');}
for(const [n,k] of [[3,3],[4,3],[5,2],[6,4]])civilQ('数量关系','最不利构造',`袋中有${n}种颜色的球，各色数量足够。至少摸出多少个，才能保证有${k}个同色球？`,n*(k-1)+1,[n*k,n+k,n*(k-1)],`每色最多${k-1}个仍不满足，共${n*(k-1)}个；再摸1个必满足，故${n*(k-1)+1}。`,'pigeon');
civilQ('数量关系','倍数特性','某班男女人数为3:2，总人数可能是以下哪个数？','45',['41','42','43'],'总份数3+2=5，总人数应为5的倍数，只有45。比例必须是精确比例。','divisible');
civilQ('数量关系','容斥','80人中40人会A技能、30人会B技能、10人都会。两种都不会的有多少人？','20',['10','30','40'],'至少一种=40+30−10=60，两种都不会=80−60=20。','inclusion');
civilQ('数量关系','追及','快车每小时60千米，慢车每小时40千米，同向且慢车领先100千米，同时匀速前进，快车几小时追上？','5',['2','2.5','10'],'相对速度60−40=20，时间100÷20=5小时。','motion');
civilQ('数量关系','平方差','98×102等于多少？','9996',['9998','10004','9804'],'(100−2)(100+2)=10000−4=9996。只有对称中心相同时才能这样直接用。','square');
civilQ('数量关系','代入排除','某整数加3后能被5整除，下列哪个可能是这个整数？','12',['14','16','18'],'12+3=15可被5整除；其他为17、19、21，均不可。','substitute');
const logicRows=[['所有通过检测的设备均已登记。甲设备未登记。可以推出：','甲设备未通过检测',['甲设备已通过检测','甲设备已登记','所有未检测设备都未登记'],'通过→登记，逆否为未登记→未通过。','logic'],['定义：公益志愿服务指自愿、无偿提供的社会服务。以下符合定义的是：','小林自愿且无偿参加社区服务',['被要求强制劳动','领取约定报酬提供服务','为个人生意推销产品'],'逐要件：自愿、无偿、社会服务，全部满足才可。','definition'],['“麻雀：鸟”的关系与哪组最接近？','苹果：水果',['车轮：汽车','钥匙：开锁','雨：湿润'],'麻雀是鸟的一种，是种属关系；苹果是水果的一种。车轮与汽车是组成。','analogy'],['某校培训后平均成绩提高，据此断言培训导致提高。哪项最能削弱？','同期试卷难度显著下降',['培训老师很认真','教室换了窗帘','学校名字没有改变'],'试卷变简单是能直接解释成绩提高的他因，削弱唯一归因。','argument'],['所有A都是B，且小李是B。下列哪项一定成立？','无法据此断定小李是否为A',['小李一定是A','小李一定不是A','所有B都是A'],'A→B不能肯定后件推出前件。','logic'],['某序列图形的封闭区域数依次1、2、3、4，且其他特征相同。依该规则下一图应有几个封闭区域？','5',['4','6','8'],'在题干已明确计数规则的条件下按1、2、3、4、5递增。真实图推需验证所有图。','graph']];
logicRows.forEach(r=>civilQ('判断推理',r[4]==='logic'?'翻译推理':'关系与论证',r[0],r[1],r[2],r[3],r[4]));
const verbalRows=[['技术工具能提高处理速度，但只有做好人员培训，工具才能发挥作用。这段话重点强调：','培训对工具落地的重要性',['应当彻底放弃技术','技术自动解决一切问题','所有培训都没有价值'],'转折后强调工具发挥作用的条件，既不否定技术也不夸大培训。','central'],['团队既要追求效率，也要保证质量，不能____。最合适的是：','顾此失彼',['循序渐进','相辅相成','精益求精'],'语境强调兼顾两项，不能顾了这个丢了那个。','fill'],['排序：①这一方案经过试点后得到完善。②团队提出了新方案。③随后开始全面推广。正确顺序是：','②①③',['①②③','③②①','②③①'],'先提出方案，才可指代“这一方案”，试点完善后“随后”推广。','order'],['有人提出增加设备数量，而调查显示效率瓶颈主要在流程衔接。最符合文意的是：','应重视流程衔接问题',['设备越多效率必越高','所有设备均无作用','无需进行任何改进'],'中心是实际瓶颈，避免推成对设备的全面否定。','central'],['阅读不能只追求速度，还应____内容之间的联系。最恰当的是：','把握',['贩卖','切断','隐瞒'],'把握联系符合阅读理解语境与动宾搭配。','fill'],['排列：①因此需要明确交接标准。②不同岗位之间信息容易遗漏。③交接记录不完整是造成遗漏的原因之一。顺序是：','②③①',['①②③','③①②','②①③'],'先陈述现象，再说明原因，最后“因此”提出对策。','order']];verbalRows.forEach(r=>civilQ('言语理解与表达','阅读与表达',r[0],r[1],r[2],r[3],r[4]));
[['1千瓦时表示哪一种物理量？','能量',['功率','速度','温度'],'千瓦是功率，乘时间后为能量；1千瓦时=3.6×10^6焦耳。'],['下列哪个是速度单位？','米/秒',['米','秒','千克'],'速度=路程÷时间，量纲是长度/时间。'],['地球绕太阳运行一周所对应的时间尺度最接近：','一年',['一天','一小时','一周'],'公转周期对应年，自转周期与日有关。'],['通常情况下，声音不能在哪种环境传播？','真空',['空气','水','钢铁'],'声波需要介质；光在真空中可以传播。'],['同为常温常压条件下，水结冰通常伴随什么体积变化？','体积增大',['体积变为零','体积恒定','质量翻倍'],'冰的密度小于水，同质量体积增大。条件和物态要分清。'],['下列表示存储容量而非功率的是：','GB',['W','kW','MW'],'GB是数据容量单位，W及其倍数表示功率。']].forEach(r=>civilQ('常识判断','科技常识',r[0],r[1],r[2],r[3],'units'));
[['调查发现两项指标同时上升，就断言其中一项必然导致另一项。这忽视了：','相关关系不等于因果关系',['两项数据不能同时存在','任何调查都毫无价值','所有指标完全相同'],'因果判断还需时间顺序、机制和排除其他原因等证据。'],['制定措施前先调查不同社区的实际情况，主要体现：','从实际出发',['用单一经验替代调查','不需要验证','先作结论再找理由'],'认识具体条件，再制定措施，避免脱离现实。'],['既承认问题有共性，又分析各地差异，较恰当的做法是：','在共同原则下因地制宜',['无视所有差异','只凭个人喜好','任何经验都不能参考'],'共性与个性结合，不把通用原则机械照搬。'],['某项改革既有收益也有成本，评估时应：','全面分析收益、成本与受影响群体',['只看一项有利数据','认为有成本就不能做','忽略长期效果'],'综合分析不同方面与长期短期影响，避免片面性。']].forEach(r=>civilQ('政治理论','基本思维方法',r[0],r[1],r[2],r[3],'read'));
